def num_magic_squares_inside(grid: List[List[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    digits = set(range(1, 10))

    def is_magic(r: int, c: int) -> bool:
        if grid[r + 1][c + 1] != 5:          # every 1..9 magic square has 5 in the middle
            return False
        cells = [grid[r + i][c + j] for i in range(3) for j in range(3)]
        if set(cells) != digits:
            return False
        lines = [cells[0:3], cells[3:6], cells[6:9],               # rows
                 cells[0::3], cells[1::3], cells[2::3],             # columns
                 [cells[0], cells[4], cells[8]], [cells[2], cells[4], cells[6]]]
        return all(sum(line) == 15 for line in lines)

    return sum(is_magic(r, c) for r in range(rows - 2) for c in range(cols - 2))

def get_happy_string(n: int, k: int) -> str:
    block = 1 << (n - 1)              # strings that share a given first letter
    if k > 3 * block:
        return ""
    idx = k - 1
    out = ["abc"[idx // block]]
    idx %= block
    for pos in range(n - 1):
        block >>= 1
        allowed = [ch for ch in "abc" if ch != out[-1]]   # two options, alphabetical
        out.append(allowed[idx // block])
        idx %= block
    return "".join(out)

def can_be_increasing(nums: List[int]) -> bool:
    def increasing_without(skip: int) -> bool:
        prev = None
        for i, x in enumerate(nums):
            if i == skip:
                continue
            if prev is not None and x <= prev:
                return False
            prev = x
        return True

    for i in range(1, len(nums)):
        if nums[i - 1] >= nums[i]:
            # one of the two elements of the first bad pair must be removed
            return increasing_without(i - 1) or increasing_without(i)
    return True

