def super_egg_drop(k: int, n: int) -> int:
    cover = [0] * (k + 1)     # cover[j]: floors resolvable with the current moves and j eggs
    moves = 0
    while cover[k] < n:
        moves += 1
        for j in range(k, 0, -1):
            # drop once: floors below (egg breaks) + floors above (egg survives) + this floor
            cover[j] = cover[j - 1] + cover[j] + 1
    return moves

def max_students(seats: List[List[str]]) -> int:
    width = len(seats[0])
    dp = {0: 0}                                  # mask of previous row -> best total
    for row in seats:
        broken = sum(1 << j for j, ch in enumerate(row) if ch == "#")
        new = {}
