def remove_leaf_nodes(root: Optional[TreeNode], target: int) -> Optional[TreeNode]:
    # BFS order lists parents before children; walking it backwards handles children first
    order = [(root, None)]
    for node, _ in order:
        if node.left:
            order.append((node.left, node))
        if node.right:
            order.append((node.right, node))
    for node, parent in reversed(order):
        if node.left is None and node.right is None and node.val == target:
