def max_subarrays(n: int, conflictingPairs: List[List[int]]) -> int:
    lefts_by_right = [[] for _ in range(n + 1)]
    for a, b in conflictingPairs:
        if a > b:
            a, b = b, a
        lefts_by_right[b].append(a)
    gain = [0] * (n + 1)       # gain[a]: extra subarrays if the pair supplying top1 = a is removed
    top1 = top2 = 0            # largest and second largest left value seen so far
    base = 0
    for r in range(1, n + 1):
        for a in lefts_by_right[r]:
            if a > top1:
                top1, top2 = a, top1
            elif a > top2:
                top2 = a
        base += r - top1
        gain[top1] += top1 - top2
    return base + max(gain)

