def merge_stones(stones: List[int], k: int) -> int:
    n = len(stones)
    if (n - 1) % (k - 1):
        return -1                  # each merge removes exactly k - 1 piles
    prefix = [0]
    for s in stones:
        prefix.append(prefix[-1] + s)
    # dp[i][j]: min cost to squeeze stones[i..j] into (j - i) % (k - 1) + 1 piles
    dp = [[0] * n for _ in range(n)]
    for length in range(k, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            best = float("inf")
            for mid in range(i, j, k - 1):   # stones[i..mid] becomes a single pile
                best = min(best, dp[i][mid] + dp[mid + 1][j])
            if (j - i) % (k - 1) == 0:
                best += prefix[j + 1] - prefix[i]   # final merge into one pile
            dp[i][j] = best
    return dp[0][n - 1]

