def unique_xor_triplets(nums: List[int]) -> int:
    distinct = set(nums)
    if len(distinct) <= 32:
        # few distinct values: enumerate pair XORs, then XOR each with every value
        pairs = {a ^ b for a in distinct for b in distinct}
        return len({p ^ c for p in pairs for c in distinct})
    size = 1 << max(nums).bit_length()  # every XOR of these values fits below this power of two

    def walsh_hadamard(a: list) -> None:
        h = 1
        while h < size:
            for start in range(0, size, 2 * h):
                lo, hi = a[start:start + h], a[start + h:start + 2 * h]
                a[start:start + h] = [x + y for x, y in zip(lo, hi)]
                a[start + h:start + 2 * h] = [x - y for x, y in zip(lo, hi)]
            h *= 2

    f = [0] * size
    for v in distinct:
        f[v] = 1
    walsh_hadamard(f)
    f = [x * x * x for x in f]          # XOR convolution of three copies
    walsh_hadamard(f)                   # inverse transform up to a factor of size
    return sum(1 for x in f if x != 0)

