def odd_even_jumps(arr: list[int]) -> int:
    n = len(arr)

    def next_targets(order):
        # For indices listed in 'order', find for each one the first later index
        # in that order which is also to its right in the array.
        target = [None] * n
        stack = []
        for i in order:
            while stack and stack[-1] < i:
                target[stack.pop()] = i
            stack.append(i)
        return target

    higher = next_targets(sorted(range(n), key=lambda i: (arr[i], i)))
    lower = next_targets(sorted(range(n), key=lambda i: (-arr[i], i)))

    odd = [False] * n   # can finish if the next jump is odd
    even = [False] * n  # can finish if the next jump is even
    odd[n - 1] = even[n - 1] = True
    for i in range(n - 2, -1, -1):
        if higher[i] is not None:
            odd[i] = even[higher[i]]
        if lower[i] is not None:
            even[i] = odd[lower[i]]
    return sum(odd)

