class Robot:
    def __init__(self, width: int, height: int):
        self.w = width
        self.h = height
        self.perimeter = 2 * (width - 1 + height - 1)
        self.pos = 0          # offset along the border cycle
        self.moved = False    # (0, 0) faces East only before the first move

    def step(self, num: int) -> None:
        self.moved = True
        self.pos = (self.pos + num) % self.perimeter

    def _locate(self):
        w, h, p = self.w, self.h, self.pos
        if p == 0:
            return [0, 0], "South" if self.moved else "East"
        if p <= w - 1:
            return [p, 0], "East"
        p -= w - 1
        if p <= h - 1:
            return [w - 1, p], "North"
        p -= h - 1
        if p <= w - 1:
            return [w - 1 - p, h - 1], "West"
        p -= w - 1
        return [0, h - 1 - p], "South"

    def getPos(self) -> List[int]:
        return self._locate()[0]

    def getDir(self) -> str:
        return self._locate()[1]

