def min_cost(houses: list[int], cost: list[list[int]], m: int, n: int, target: int) -> int:
    INF = float("inf")
    # dp[k][c]: min cost so far with k neighborhoods, last house color c (0 based)
    dp = [[INF] * n for _ in range(target + 1)]
    first = houses[0]
    for c in range(n):
        if first == 0:
            dp[1][c] = cost[0][c]
        elif first == c + 1:
            dp[1][c] = 0

    for i in range(1, m):
        # smallest and second smallest of each row, plus the color of the smallest
        stats = []
        for k in range(target + 1):
            row = dp[k]
            best_c, best, second = -1, INF, INF
            for c in range(n):
                v = row[c]
                if v < best:
                    second, best, best_c = best, v, c
                elif v < second:
                    second = v
            stats.append((best_c, best, second))

        colors = range(n) if houses[i] == 0 else [houses[i] - 1]
        new = [[INF] * n for _ in range(target + 1)]
        for k in range(1, min(i + 1, target) + 1):
            prev_c, prev_best, prev_second = stats[k - 1]
            for c in colors:
                paint = cost[i][c] if houses[i] == 0 else 0
                start_new = prev_second if prev_c == c else prev_best
                best = min(dp[k][c], start_new)
                if best < INF:
                    new[k][c] = best + paint
        dp = new

    answer = min(dp[target])
    return -1 if answer == INF else answer

def smallest_good_base(n: str) -> str:
    num = int(n)

    def repunit(k, digits, limit):
        # 1 + k + ... + k^(digits - 1), stopping early once it exceeds limit
        total, term = 0, 1
        for _ in range(digits):
            total += term
            if total > limit:
                return total
            term *= k
        return total

    for digits in range(num.bit_length() + 1, 2, -1):
        # k^(digits - 1) < num, so k is below num ** (1 / (digits - 1)) + 1
        lo, hi = 2, int(num ** (1.0 / (digits - 1))) + 1
        while lo <= hi:
            k = (lo + hi) // 2
            value = repunit(k, digits, num)
            if value == num:
                return str(k)
            if value < num:
                lo = k + 1
            else:
                hi = k - 1
    return str(num - 1)  # "11" in base num - 1

