            cur = cur.left
        cur = stack.pop()
        nodes.append(cur)
        cur = cur.right

    def build(lo, hi):
        # balanced BST from nodes[lo..hi]; depth is O(log n)
        if lo > hi:
            return None
        mid = (lo + hi) // 2
        node = nodes[mid]
        node.left = build(lo, mid - 1)
        node.right = build(mid + 1, hi)
        return node

    return build(0, len(nodes) - 1)

