def find_the_longest_substring(s: str) -> int:
    bit = {"a": 1, "e": 2, "i": 4, "o": 8, "u": 16}
    first_seen = [-2] * 32   # -2 means the mask has not appeared yet
    first_seen[0] = -1       # empty prefix
    mask = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in bit:
            mask ^= bit[ch]
        if first_seen[mask] == -2:
            first_seen[mask] = i
        else:
            best = max(best, i - first_seen[mask])
    return best

