def pyramid_transition(bottom: str, allowed: list[str]) -> bool:
    above = defaultdict(list)  # (left, right) -> letters allowed on top
    for pattern in allowed:
        above[pattern[:2]].append(pattern[2])

    @lru_cache(maxsize=None)
    def can_finish(row):
        if len(row) == 1:
            return True
        # every adjacent pair must have at least one option
        if any(row[i:i + 2] not in above for i in range(len(row) - 1)):
            return False

        def fill(i, built):
            if i == len(row) - 1:
                return can_finish("".join(built))
            for top in above[row[i:i + 2]]:
                built.append(top)
                if fill(i + 1, built):
                    return True
                built.pop()
            return False

        return fill(0, [])

    return can_finish(bottom)

def get_ancestors(n: int, edges: list[list[int]]) -> list[list[int]]:
    children = [[] for _ in range(n)]
    for a, b in edges:
        children[a].append(b)

    answer = [[] for _ in range(n)]
    seen = [-1] * n  # seen[w] == u when w was reached from source u
    for u in range(n):
        stack = [u]
        seen[u] = u
        while stack:
            node = stack.pop()
            for nxt in children[node]:
                if seen[nxt] != u:
                    seen[nxt] = u
                    answer[nxt].append(u)  # sources are increasing, so lists stay sorted
                    stack.append(nxt)
    return answer

