def max_probability(n: int, edges: list[list[int]], succProb: list[float],
                    start_node: int, end_node: int) -> float:
    graph = [[] for _ in range(n)]
    for (a, b), p in zip(edges, succProb):
        graph[a].append((b, p))
        graph[b].append((a, p))

    best = [0.0] * n
    best[start_node] = 1.0
    heap = [(-1.0, start_node)]  # negated probabilities make a max heap
    while heap:
        neg, u = heapq.heappop(heap)
        prob = -neg
        if u == end_node:
            return prob
        if prob < best[u]:
            continue  # stale entry
        for v, p in graph[u]:
            candidate = prob * p
            if candidate > best[v]:
                best[v] = candidate
                heapq.heappush(heap, (-candidate, v))
    return 0.0

