def count_valid_words(sentence: str) -> int:
    def valid(token):
        hyphens = 0
        last = len(token) - 1
        for i, ch in enumerate(token):
            if ch.isdigit():
                return False
            if ch == "-":
                hyphens += 1
                if (hyphens > 1 or i == 0 or i == last
                        or not token[i - 1].isalpha() or not token[i + 1].isalpha()):
                    return False
            elif ch in "!.,":
                if i != last:
                    return False
        return True

    return sum(1 for token in sentence.split() if valid(token))

