def ideal_arrays(n: int, maxValue: int) -> int:
    MOD = 10**9 + 7
    LIMIT = n + 15  # exponents are at most 13 for maxValue <= 10^4
    fact = [1] * LIMIT
    for i in range(1, LIMIT):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * LIMIT
    inv_fact[-1] = pow(fact[-1], MOD - 2, MOD)
    for i in range(LIMIT - 1, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def ways(e):
        # C(n - 1 + e, e): spread e exponent increments over n positions
        return fact[n - 1 + e] * inv_fact[e] % MOD * inv_fact[n - 1] % MOD

    # smallest prime factor sieve
    spf = list(range(maxValue + 1))
    for p in range(2, int(maxValue ** 0.5) + 1):
        if spf[p] == p:
            for multiple in range(p * p, maxValue + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    total = 0
    for v in range(1, maxValue + 1):
        count = 1
        x = v
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            count = count * ways(e) % MOD
        total += count
    return total % MOD

