def has_same_digits(s: str) -> bool:
    d = [ord(c) - 48 for c in s]
    m = len(d) - 2
    inv = {1: 1, 3: 7, 7: 3, 9: 9}          # inverses of units modulo 10
    pow2 = (6, 2, 4, 8)                       # 2^a mod 10 for a >= 1, indexed by a % 4
    unit, e2, e5 = 1, 0, 0                    # C(m, 0) = 1
    first = second = 0
    for i in range(m + 1):
        if i > 0:
            # C(m, i) = C(m, i - 1) * (m - i + 1) / i
            x, y = m - i + 1, i
            while x % 2 == 0:
                x //= 2; e2 += 1
            while x % 5 == 0:
                x //= 5; e5 += 1
            while y % 2 == 0:
                y //= 2; e2 -= 1
            while y % 5 == 0:
                y //= 5; e5 -= 1
            unit = unit * (x % 10) * inv[y % 10] % 10
        if e2 and e5:
            coef = 0
        elif e5:
            coef = 5
        elif e2:
            coef = unit * pow2[e2 % 4] % 10
        else:
            coef = unit
        if coef:
            first += coef * d[i]
            second += coef * d[i + 1]
    return first % 10 == second % 10

