def constrained_subset_sum(nums: List[int], k: int) -> int:
    best = [0] * len(nums)
    window = deque()               # indices with decreasing best values
    answer = nums[0]
    for i, value in enumerate(nums):
        if window and window[0] < i - k:
            window.popleft()       # too far back to be a predecessor
        prev = best[window[0]] if window else 0
        best[i] = value + (prev if prev > 0 else 0)
        if best[i] > answer:
            answer = best[i]
        while window and best[window[-1]] <= best[i]:
            window.pop()
        window.append(i)
    return answer

def smallest_distance_pair(nums: List[int], k: int) -> int:
    a = sorted(nums)
    n = len(a)

    def pairs_within(d: int) -> int:
        # number of pairs (i < j) with a[j] - a[i] <= d
        count = left = 0
        for right in range(n):
            while a[right] - a[left] > d:
                left += 1
            count += right - left
        return count

    lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if pairs_within(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def num_similar_groups(strs: List[str]) -> int:
    n = len(strs)
    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def similar(a: str, b: str) -> bool:
        diff = 0
        for x, y in zip(a, b):
            if x != y:
                diff += 1
                if diff > 2:
                    return False
        return True                  # 0 or 2 mismatches (anagrams never give 1)

    groups = n
    for i in range(n):
        for j in range(i + 1, n):
            ri, rj = find(i), find(j)
            if ri != rj and similar(strs[i], strs[j]):
                parent[ri] = rj
                groups -= 1
    return groups

